{
  "name": "ancplua-claude-plugins",
  "owner": {
    "name": "AncpLua",
    "url": "https://github.com/ANcpLua"
  },
  "metadata": {
    "description": "Claude Code plugin marketplace: 9 plugins, 24 commands, 4 skills, 19 agents. Multi-agent orchestration, cognitive amplification, OpenTelemetry docs, .NET build enforcement, and compile-time instrumentation."
  },
  "plugins": [
    {
      "name": "metacognitive-guard",
      "description": "Cognitive amplification stack: epistemic hooks, competitive review, commit integrity checks, CI verification scripts, and deep-thinking agents.",
      "version": "0.4.5",
      "source": "./plugins/metacognitive-guard"
    },
    {
      "name": "otelwiki",
      "description": "OpenTelemetry documentation with auto-sync. Semantic conventions, collector config, .NET instrumentation.",
      "version": "1.0.6",
      "source": "./plugins/otelwiki"
    },
    {
      "name": "dotnet-architecture-lint",
      "description": "Enforces .NET build patterns: Version.props symlinks, CPM, and single-owner imports. Prevents AI agents from breaking centralized version management.",
      "version": "1.1.0",
      "source": "./plugins/dotnet-architecture-lint"
    },
    {
      "name": "hookify",
      "description": "User-configurable hooks from .local.md files. Define blocking and warning rules for Bash commands, file edits, and session events.",
      "version": "0.2.0",
      "source": "./plugins/hookify"
    },
    {
      "name": "feature-dev",
      "description": "Guided feature development with specialized agents for codebase exploration, architecture design, code review, and quality assurance.",
      "version": "1.2.0",
      "source": "./plugins/feature-dev"
    },
    {
      "name": "ancplua-project-routing",
      "description": "Auto-routes to specialist agents, commands, and skills based on current project. Injects cross-repo dependency graph for the ancplua .NET ecosystem.",
      "version": "2.0.0",
      "source": "./plugins/ancplua-project-routing"
    },
    {
      "name": "council",
      "description": "Five-agent council using Teams API: Opus captain orchestrates, researcher + synthesizer cross-pollinate via SendMessage, clarity asks live follow-ups, Haiku janitor flags bloat. Reactive collaboration instead of fire-and-forget subagents.",
      "version": "1.2.0",
      "source": "./plugins/council"
    },
    {
      "name": "exodia",
      "description": "Multi-agent workflow orchestration (9 commands + 2 skills: eight-gates, hades): fix, turbo-fix, fix-pipeline, tournament, mega-swarm, deep-think, batch-implement, red-blue-review, baryon-mode. Hades, eight-gates, and red-blue-review use Teams API for reactive collaboration.",
      "version": "2.1.0",
      "source": "./plugins/exodia"
    },
    {
      "name": "qyl-instrumentation",
      "description": "Teams API observability orchestration for qyl: 1 Opus captain + 4 Sonnet specialists. Captain pre-reads otelwiki semconv docs, dispatches servicedefaults, collector, genai, and platform specialists. Zero runtime web search.",
      "version": "2.1.0",
      "source": "./plugins/qyl-instrumentation"
    }
  ]
}
